import { z } from "zod";
import { builtin } from "./identity.ts";

/** Provenance attached to a host title assignment generated by the builtin paradigm. */
export const AutomaticSessionName = builtin.data("session.automatic-name", z.strictObject({
  level: z.enum(["initial", "refined"]),
  messageId: z.string(),
  model: z.string(),
}));
